// The shape of mixpanel-browser 2.85.0's src/index.d.ts, reduced: top-level exports, not an
// ambient module, so the extractor finds the package from node_modules.
export interface Dict {
  [key: string]: any;
}
export interface Config {
  [key: string]: any;
}
export interface People {
  set(prop: string, to: any): void;
  set(prop: Dict): void;
}
export interface Mixpanel {
  init(token: string, config: Partial<Config>, name?: string): Mixpanel;
  track(event_name: string, properties?: Dict): void;
  people: People;
}
export interface OverridedMixpanel extends Mixpanel {
  init(token: string, config: Partial<Config>, name: string): Mixpanel;
  init(token: string, config?: Partial<Config>): undefined;
}
export function init(token: string, config?: Partial<Config>): undefined;
export function track(event_name: string, properties?: Dict): void;
export const people: People;
declare const mixpanel: OverridedMixpanel;
export default mixpanel;
